import numpy as np
import matplotlib.pyplot as plt
import re
from collections import Counter

def task_func(mystrings, text):
    def _is_empty(value):
        if value is None:
            return True
        if isinstance(value, str):
            return value.strip() == ""
        try:
            return len(value) == 0
        except TypeError:
            return False

    if _is_empty(text):
        raise ValueError("Input text is empty")

    if isinstance(text, str):
        fallback_words = [token for token in re.split(r"\s+", text.strip()) if token]
    else:
        try:
            fallback_words = list(text)
        except TypeError:
            fallback_words = [text]

    if mystrings is None:
        words = fallback_words
    elif isinstance(mystrings, str):
        words = [mystrings]
    else:
        try:
            words = list(mystrings)
        except TypeError:
            words = [mystrings]

    if not words:
        words = fallback_words

    normalized_words = [str(word).lower().replace(" ", "_") for word in words]
    counts = Counter(normalized_words)

    ordered_unique_words = []
    seen = set()
    for word in normalized_words:
        if word not in seen:
            seen.add(word)
            ordered_unique_words.append(word)

    fig, ax = plt.subplots()
    x = np.arange(len(ordered_unique_words))
    y = [counts[word] for word in ordered_unique_words]

    ax.bar(x, y)
    ax.set_xticks(x)
    ax.set_xticklabels(ordered_unique_words, rotation=45, ha="right")
    ax.set_xlabel("Words")
    ax.set_ylabel("Frequency")
    ax.set_title("Word Frequency Plot")
    fig.tight_layout()

    return ax
